import{_ as a,o as i,c as t,a2 as n}from"./chunks/framework.1lR7qgqY.js";const c=JSON.parse('{"title":"M2 使用者介面與反向代理","description":"","frontmatter":{},"headers":[],"relativePath":"build/m2-ui-proxy.md","filePath":"build/m2-ui-proxy.md","lastUpdated":null}'),e={name:"build/m2-ui-proxy.md"};function l(p,s,d,h,o,r){return i(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="m2-使用者介面與反向代理" tabindex="-1">M2 使用者介面與反向代理 <a class="header-anchor" href="#m2-使用者介面與反向代理" aria-label="Permalink to &quot;M2 使用者介面與反向代理&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ● 必要</li><li>狀態: 可閱讀 (指令未實機驗證)</li><li>資料基準日: 2026-10-26</li><li>待查證: 反向代理一節僅有大綱</li></ul></div><p><strong>結論</strong>: 介面讓使用者能在瀏覽器裡和模型對話, 反向代理讓連線加密, 並在介面前面多一道驗證與流量控制. 單人單機只需要介面, 而且只綁 127.0.0.1; 要讓內網其他人連入時, 才在前面加反向代理.</p><p><strong>這一塊在圖上的位置</strong>: VM 入口區的 Open WebUI 與 Nginx 或 Caddy. <strong>前置模組</strong>: M1. <strong>完成後的狀態</strong>: 里程碑 1 完成, 可以在瀏覽器裡和本機模型對話.</p><h2 id="m2-1-選擇介面" tabindex="-1">M2.1 選擇介面 <a class="header-anchor" href="#m2-1-選擇介面" aria-label="Permalink to &quot;M2.1 選擇介面&quot;">​</a></h2><p>等級 A 與 C 建議用 AnythingLLM 桌面版, 其他等級用 Open WebUI 單一容器. 不加閘道, 代理框架與 MCP.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[瀏覽器 / 桌面 App]</span></span>
<span class="line"><span>      | http://127.0.0.1:3000</span></span>
<span class="line"><span>      v</span></span>
<span class="line"><span>[Open WebUI 或 AnythingLLM] ----&gt; [Ollama / llama-server]</span></span>
<span class="line"><span>      |</span></span>
<span class="line"><span>   (本機資料卷: 對話, 設定) --&gt; 每週備份</span></span>
<span class="line"><span>   對外: 無開放連接埠</span></span></code></pre></div><h2 id="m2-2-用-docker-執行介面時的連接埠與位址" tabindex="-1">M2.2 用 Docker 執行介面時的連接埠與位址 <a class="header-anchor" href="#m2-2-用-docker-執行介面時的連接埠與位址" aria-label="Permalink to &quot;M2.2 用 Docker 執行介面時的連接埠與位址&quot;">​</a></h2><p>用容器跑介面時, 有兩件事容易做錯 (指令未實機驗證, 依下列官方文件整理):</p><ol><li><strong>發布連接埠時要指定 127.0.0.1.</strong> Docker 官方文件指出, <code>-p 8080:80</code> 會綁定在主機的任一位址, 要限制只有主機本身能存取, 須寫成 <code>-p 127.0.0.1:8080:80</code> (來源: Docker 文件 Port publishing and mapping). 此外, Docker 官方文件說明 Docker 與 ufw 的防火牆規則運作方式不相容, 已發布的連接埠可能不受 ufw 規則限制 (來源: Docker 文件 Packet filtering and firewalls). 因此「用 ufw 擋住」不能當作唯一防線, 發布時就要綁定 127.0.0.1.</li><li><strong>容器內的 127.0.0.1 指的是容器自己.</strong> 要從容器連到主機上的 Ollama, Open WebUI 官方文件建議使用 <code>host.docker.internal</code>, 並在 Linux 加上 <code>--add-host=host.docker.internal:host-gateway</code> (來源: Open WebUI 文件 Quick Start).</li></ol><p>範例 (以 Open WebUI 官方 Quick Start 的指令為基礎, 僅把發布位址改為 127.0.0.1, 並固定版本標籤):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> 127.0.0.1:3000:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#F47067;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;">  --add-host=host.docker.internal:host-gateway</span><span style="--shiki-light:#005CC5;--shiki-dark:#F47067;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;">  -v</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> open-webui:/app/backend/data</span><span style="--shiki-light:#005CC5;--shiki-dark:#F47067;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> WEBUI_SECRET_KEY=&quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> rand </span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;">-hex</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> 32</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">)&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#F47067;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;">  --name</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> open-webui</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> --restart</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> always</span><span style="--shiki-light:#005CC5;--shiki-dark:#F47067;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">  ghcr.io/open-webui/open-webui:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">固定版本標</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">籤</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">&gt;</span></span></code></pre></div><p><code>WEBUI_SECRET_KEY</code> 請存入 <code>.env</code> 並沿用, 否則重建容器後所有人須重新登入 (來源: Open WebUI Quick Start). 官方範例使用浮動的 <code>:main</code> 標籤, 本手冊建議改用固定版本 (見 O2).</p><p><strong>尚待實機驗證的取捨 (推論, 信心: 中高)</strong>: Ollama 預設只綁 127.0.0.1:11434 (來源: Ollama FAQ). 在 Linux 上, 容器經 <code>host-gateway</code> 連主機時, 流量不是從主機的 127.0.0.1 進入, 因此預設設定下可能連不到. 常見解法有三種, 各有取捨:</p><table tabindex="0"><thead><tr><th>做法</th><th>作法</th><th>風險</th></tr></thead><tbody><tr><td>讓 Ollama 也跑在容器, 與介面共用 Docker 網路</td><td>不發布 Ollama 的連接埠</td><td>最單純; 需設定 GPU 直通 (依 Ollama 與 Docker 官方文件)</td></tr><tr><td>把 <code>OLLAMA_HOST</code> 改為 <code>0.0.0.0:11434</code></td><td>以 systemd 設定 (見 M1)</td><td>區域網路內其他裝置也連得到 11434, 須搭配主機防火牆</td></tr><tr><td>介面容器改用主機網路 (<code>--network=host</code>)</td><td>不經 Docker NAT</td><td>容器與主機共用網路, 隔離變弱</td></tr></tbody></table><p>建議優先採用第一種. 若採第二種, 請確認防火牆規則在 Docker 之外也有效, 並以另一台裝置實際掃描 11434 連接埠.</p><h2 id="m2-3-加上反向代理-內網多人連入時" tabindex="-1">M2.3 加上反向代理 (內網多人連入時) <a class="header-anchor" href="#m2-3-加上反向代理-內網多人連入時" aria-label="Permalink to &quot;M2.3 加上反向代理 (內網多人連入時)&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>Nginx 與 Caddy 的取捨: Nginx 內建速率限制; Caddy 憑證設定較簡單, 速率限制須另裝外掛</li><li>內網憑證的取得方式 (公司內部憑證機構或 Caddy 的內部憑證)</li><li>只接受內網網段, 介面改綁 127.0.0.1 或 Docker 內部網路</li><li>基本驗證與速率限制的設定範例 (依官方文件驗證後補上)</li></ul><h2 id="m2-4-驗收測試" tabindex="-1">M2.4 驗收測試 <a class="header-anchor" href="#m2-4-驗收測試" aria-label="Permalink to &quot;M2.4 驗收測試&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>從本機瀏覽器完成一次對話</li><li>從內網另一台裝置只能經反向代理連入, 直接連介面的連接埠應失敗</li><li>以另一台裝置掃描主機, 確認沒有多餘的開放連接埠</li></ul>`,22)])])}const g=a(e,[["render",l]]);export{c as __pageData,g as default};
